package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ProblemInvestigationsAcceptance {
 static String api(String table,String id){return "/api/openservice/"+table+"/"+id+"/investigation";}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{assertEquals(200,r.statusCode(),html(r));return object(parsed(r).get("result"));}
 static Map<String,Object> get(WorkflowSupport h,String table,String id,String user)throws Exception{return result(h.get(api(table,id),auth(user)));}
 static int revision(Map<String,Object> item){return Integer.parseInt(item.get("sys_mod_count").toString());}
 static Map<String,Object> link(WorkflowSupport h,String incident,String operation)throws Exception{return map("operation",operation,"revision",revision(object(get(h,"incident",incident,"admin").get("incident"))));}
 static Map<String,Object> notes(WorkflowSupport h,String problem,boolean publish)throws Exception{var page=get(h,"problem",problem,"admin");return map("revision",object(page.get("analysis")).get("revision"),"record_revision",revision(object(page.get("problem"))),"cause","Root <script> cause","workaround","Restart the affected worker","publish",publish);}
 static void access(WorkflowSupport h,String table,String id,String visibility,String owner)throws Exception{assertEquals(200,h.json("PATCH","/api/openservice/access/"+table+"/"+id,map("visibility",visibility,"owner_id",owner),auth("admin")).statusCode());}
 static void run(WorkflowSupport h)throws Exception{
  h.account("ProblemAgent","agent");h.account("ProblemReader","reader");String incident=h.add("incident").get("sys_id").toString();var empty=get(h,"incident",incident,"admin");assertNull(empty.get("problem"));assertEquals(false,empty.get("has_link"));
  String owner;try(var db=h.store.open()){owner=RecordAccess.owner(db,"admin");}access(h,"incident",incident,"private",owner);
  var create=link(h,incident,"create");create.putAll(map("summary","Investigate repeated outage","details","Original evidence"));var first=result(h.json("POST",api("incident",incident),create,auth("admin")));String problem=object(first.get("problem")).get("sys_id").toString();assertEquals("",first.get("workaround"));
  assertEquals(409,h.json("POST",api("incident",incident),create,auth("admin")).statusCode());create.put("revision",revision(object(first.get("incident"))));assertEquals(400,h.json("POST",api("incident",incident),create,auth("admin")).statusCode());
  try(var db=h.store.open()){assertEquals("private",RecordAccess.status(db,problem).get("visibility"));assertEquals(owner,RecordAccess.status(db,problem).get("owner_id"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_problem_link"));}
  var draft=notes(h,problem,false);var saved=result(h.json("POST",api("problem",problem),draft,auth("admin")));assertEquals(1,object(saved.get("analysis")).get("revision"));assertEquals("",get(h,"incident",incident,"admin").get("workaround"));assertEquals(409,h.json("POST",api("problem",problem),draft,auth("admin")).statusCode());
  var publish=notes(h,problem,true);result(h.json("POST",api("problem",problem),publish,auth("admin")));assertEquals("Restart the affected worker",get(h,"incident",incident,"admin").get("workaround"));new Store(h.environment);assertEquals(1,objects(get(h,"problem",problem,"admin").get("incidents")).size());
  String visible=h.add("incident").get("sys_id").toString();var attach=link(h,visible,"link");attach.put("problem_id",problem);result(h.json("POST",api("incident",visible),attach,auth("admin")));
  var hidden=get(h,"incident",visible,"ProblemAgent");assertNull(hidden.get("problem"));assertEquals("",hidden.get("workaround"));assertFalse(JSON.writeValueAsString(hidden).contains(problem));assertEquals(404,h.get(api("problem",problem),auth("ProblemAgent")).statusCode());
  access(h,"problem",problem,"workspace","");assertEquals(1,objects(get(h,"problem",problem,"ProblemAgent").get("incidents")).size());assertEquals("Restart the affected worker",get(h,"incident",visible,"ProblemAgent").get("workaround"));
  var withdraw=notes(h,problem,false);result(h.json("POST",api("problem",problem),withdraw,auth("ProblemAgent")));assertEquals("",get(h,"incident",visible,"admin").get("workaround"));
  String other=h.add("problem").get("sys_id").toString();var relink=link(h,visible,"link");relink.put("problem_id",other);result(h.json("POST",api("incident",visible),relink,auth("ProblemAgent")));assertEquals(other,object(get(h,"incident",visible,"admin").get("problem")).get("sys_id"));
  result(h.json("POST",api("incident",visible),link(h,visible,"unlink"),auth("ProblemAgent")));assertEquals(false,get(h,"incident",visible,"admin").get("has_link"));
  for(String table:List.of("incident","problem")){String id=table.equals("incident")?incident:problem;assertEquals(401,h.get(api(table,id),null).statusCode());assertEquals(403,h.get(api(table,id),auth("ProblemReader")).statusCode());assertEquals(403,h.json("POST",api(table,id),map(),auth("ProblemReader")).statusCode());assertEquals(400,h.get(api(table,id)+"?x=y",auth("admin")).statusCode());assertEquals(405,h.json("PUT",api(table,id),map(),auth("admin")).statusCode());assertEquals(404,h.get(api(table,id()),auth("admin")).statusCode());}
  assertEquals(204,h.json("DELETE","/api/now/table/problem/"+problem,map(),auth("admin")).statusCode());assertEquals(false,get(h,"incident",incident,"admin").get("has_link"));try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_problem_analysis"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_problem_link"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("ProblemAgent","agent");String incident=h.add("incident").get("sys_id").toString(),problem=h.add("problem").get("sys_id").toString();String route=api("incident",incident),analysis=api("problem",problem);var attach=link(h,incident,"link");attach.put("problem_id",problem);result(h.json("POST",route,attach,auth("admin")));
  String options="/api/openservice/incident/"+incident+"/problem-options";assertEquals(1,objects(result(h.get(options+"?q=Synthetic&limit=1&offset=0",auth("admin"))).get("items")).size());assertTrue(objects(result(h.get(options+"?q=NoMatchingProblem",auth("admin"))).get("items")).isEmpty());assertEquals(400,h.get(options+"?extra=x",auth("admin")).statusCode());assertEquals(405,h.json("POST",options,map(),auth("admin")).statusCode());
  var good=notes(h,problem,true);for(var pair:List.of(map("cause",12),map("cause","x".repeat(4001)),map("workaround",12),map("workaround","x".repeat(4001)),map("publish","true"),map("cause"," "),map("workaround"," "),map("revision","0"),map("revision",-1))){var bad=new LinkedHashMap<>(good);bad.putAll(pair);assertEquals(400,h.json("POST",analysis,bad,auth("admin")).statusCode(),bad.keySet().toString());}
  assertEquals(400,h.json("POST",analysis,map(),auth("admin")).statusCode());var stale=new LinkedHashMap<>(good);stale.put("record_revision",10);assertEquals(409,h.json("POST",analysis,stale,auth("admin")).statusCode());
  var blank=notes(h,problem,false);blank.putAll(map("cause","","workaround",""));result(h.json("POST",analysis,blank,auth("admin")));assertEquals("",object(get(h,"problem",problem,"admin").get("analysis")).get("cause"));
  assertEquals(400,h.json("POST",route,map("operation","unknown","revision",1),auth("admin")).statusCode());assertEquals(400,h.json("POST",route,map("operation","unlink","revision",1,"extra","bad"),auth("admin")).statusCode());
  var missing=link(h,incident,"link");missing.put("problem_id",id());assertEquals(404,h.json("POST",route,missing,auth("admin")).statusCode());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"problem");}var schema=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));schema.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"problem",schema);try{assertNull(get(h,"incident",incident,"ProblemAgent").get("problem"));}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  schema=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));schema.put("field_rules",map("description",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"problem",schema);try{assertEquals(403,h.get(analysis,auth("ProblemAgent")).statusCode());assertNull(get(h,"incident",incident,"ProblemAgent").get("problem"));}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  Map<String,Object> incidentSchema;try(var db=h.store.open()){incidentSchema=Service.schema(db,"incident");}schema=object(JSON.readValue(JSON.writeValueAsString(incidentSchema),Object.class));schema.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertTrue(objects(get(h,"problem",problem,"ProblemAgent").get("incidents")).isEmpty());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",incidentSchema);}
  schema=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"problem",schema);try{assertEquals(403,h.json("POST",analysis,notes(h,problem,true),auth("ProblemAgent")).statusCode());var denied=link(h,incident,"link");denied.put("problem_id",problem);assertEquals(403,h.json("POST",route,denied,auth("ProblemAgent")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  schema=object(JSON.readValue(JSON.writeValueAsString(original),Object.class));schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"problem",schema);try{String fresh=h.add("incident").get("sys_id").toString();var create=link(h,fresh,"create");create.putAll(map("summary","Must roll back","details","Do not retain on denial"));assertEquals(403,h.json("POST",api("incident",fresh),create,auth("ProblemAgent")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_record WHERE \"table\"='problem'"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_problem_link WHERE incident_id=?",fresh));}}finally{ReferencePickerAcceptance.writeSchema(h,"problem",original);}
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(int n=0;n<99;n++){String child=Service.create(db,"incident",map("short_description","Limit "+n),"admin").get("sys_id").toString();db.update("INSERT INTO os_problem_link(incident_id,problem_id) VALUES(?,?)",child,problem);}db.connection.commit();}assertEquals(100,objects(get(h,"problem",problem,"admin").get("incidents")).size());String next=h.add("incident").get("sys_id").toString();var overflow=link(h,next,"link");overflow.put("problem_id",problem);assertEquals(400,h.json("POST",api("incident",next),overflow,auth("admin")).statusCode());
  var repeat=link(h,incident,"link");repeat.put("problem_id",problem);result(h.json("POST",route,repeat,auth("admin")));assertEquals(204,h.json("DELETE","/api/now/table/incident/"+incident,map(),auth("admin")).statusCode());assertEquals(99,objects(get(h,"problem",problem,"admin").get("incidents")).size());
  assertEquals(400,h.protectedForm("/record/problem/"+problem+"/investigation",map("revision",1,"record_revision",0,"cause","c","workaround","w","publish","yes"),auth("admin")).statusCode());
 }
}
